  'EPITALON': 'PEP_EPITALON',

  // Special compounds
  'DAA': 'AA_D_ASPARTIC_ACID',
  'D_ASPARTIC_ACID': 'AA_D_ASPARTIC_ACID',
  'CAFFEINE': 'PHARMA_CAFFEINE',
  'D_RIBOSE': 'D_RIBOSE',
